using System.ServiceProcess;
using System.Text;
using System.Threading;
using System.Windows.Forms;
using Microsoft.Win32;

namespace WdpHook
{
    // =========================================================================
    // Windows Service — runs as SYSTEM (Session 0)
    // Handles: license check, spawning user-session /hooks child, self-destruct
    // =========================================================================
    internal sealed class HookService : ServiceBase
    {
        private Thread _licThread, _spawnThread;
        private volatile bool _stop;
        private volatile int  _hooksPid;

        public HookService() { ServiceName = "WdpHook"; CanStop = true; }

        protected override void OnStart(string[] args)
        {
            _stop = false;
            Program.Log("=== WdpHook service started PID=" + Process.GetCurrentProcess().Id + " ===");

            LicenseData lic;
            if (!Program.ReadLicense(out lic)) { Program.Log("No license — stopping"); Stop(); return; }
            if (!Program.VerifyLicense(lic))   { Program.Log("Bad sig — stopping");    Stop(); return; }

            string status = Program.CheckIn(lic);
            Program.Log("Initial check-in: " + status);
            if (status == "expired" || status == "revoked" || status == "invalid")
            { Program.Log("Rejected — self-removing"); Program.SelfDestruct(); Environment.Exit(0); return; }

            Program.StartLicenseLoop(lic, () => { _stop = true; });

            _spawnThread = new Thread(SpawnLoop) { IsBackground = true, Name = "SpawnLoop" };
            _spawnThread.Start();
        }

        protected override void OnStop()
        {
            _stop = true;
            Program.Log("Service stopping");
            // Kill the hooks child if alive
            try { if (_hooksPid > 0) Process.GetProcessById(_hooksPid).Kill(); } catch { }
        }

        private void SpawnLoop()
        {
            while (!_stop)
            {
                try
                {
                    if (_hooksPid > 0)
                    {
                        try { var p = Process.GetProcessById(_hooksPid); } // throws if dead
                        catch { _hooksPid = 0; Program.Log("Hooks child died — will respawn"); }
                    }
                    if (_hooksPid == 0) SpawnHooksChild();
                }
                catch (Exception ex) { Program.Log("SpawnLoop error: " + ex.Message); }
                Thread.Sleep(10000);
            }
        }

        private void SpawnHooksChild()
        {
            uint sessionId = WTSGetActiveConsoleSessionId();
            if (sessionId == 0xFFFFFFFF) { Program.Log("No active console session"); return; }

            // Get user token only for environment block
            IntPtr hUserToken = IntPtr.Zero;
            WTSQueryUserToken(sessionId, out hUserToken);

            // Use the service's SYSTEM token so the child runs at SYSTEM integrity.
            // WH_GETMESSAGE from SYSTEM can inject into any integrity level (bypasses UIPI).
            IntPtr hSvcToken = IntPtr.Zero;
            if (!OpenProcessToken(GetCurrentProcess(), TOKEN_ALL_ACCESS, out hSvcToken))
            {
                Program.Log("OpenProcessToken failed err=" + Marshal.GetLastWin32Error());
                if (hUserToken != IntPtr.Zero) CloseHandle(hUserToken);
                return;
            }
            try
            {
                IntPtr hDup = IntPtr.Zero;
                if (!DuplicateTokenEx(hSvcToken, TOKEN_ALL_ACCESS, IntPtr.Zero,
                    SecurityImpersonation, TokenPrimary, out hDup))
                { Program.Log("DuplicateTokenEx(SYSTEM) failed err=" + Marshal.GetLastWin32Error()); return; }
                try
                {
                    // Redirect the duplicated SYSTEM token to the user's desktop session
                    // so the child appears on winsta0\default rather than Session 0.
                    uint sid = sessionId;
                    if (!SetTokenInformation(hDup, TokenSessionId, ref sid, 4))
                        Program.Log("SetTokenInformation(SessionId) warn err=" + Marshal.GetLastWin32Error());

                    // Build environment from user token so PATH/TEMP/etc. are correct
                    IntPtr env = IntPtr.Zero;
                    if (hUserToken != IntPtr.Zero)
                        CreateEnvironmentBlock(out env, hUserToken, false);

                    string exe = "\"" + Program.ExePath + "\" /hooks";
                    var si = new STARTUPINFO { cb = Marshal.SizeOf(typeof(STARTUPINFO)), lpDesktop = "winsta0\\default" };
                    PROCESS_INFORMATION pi;
                    bool ok = CreateProcessAsUserW(hDup, null, exe, IntPtr.Zero, IntPtr.Zero,
                        false, CREATE_UNICODE_ENV, env, null, ref si, out pi);
                    if (env != IntPtr.Zero) DestroyEnvironmentBlock(env);

                    if (ok)
                    {
                        _hooksPid = (int)pi.dwProcessId;
                        Program.Log("Spawned /hooks child (SYSTEM session=" + sessionId + ") PID=" + _hooksPid);
                        CloseHandle(pi.hProcess); CloseHandle(pi.hThread);
                    }
                    else
                        Program.Log("CreateProcessAsUser(SYSTEM) failed err=" + Marshal.GetLastWin32Error());
                }
                finally { CloseHandle(hDup); }
            }
            finally
            {
                CloseHandle(hSvcToken);
                if (hUserToken != IntPtr.Zero) CloseHandle(hUserToken);
            }
        }

        // --- P/Invoke for user-session spawning ---
        const uint TOKEN_ALL_ACCESS      = 0xF01FF;
        const int  SecurityImpersonation = 2;
        const int  TokenPrimary          = 1;
        const uint CREATE_UNICODE_ENV    = 0x00000400;
        const int  TokenSessionId        = 12;

        [DllImport("kernel32.dll")] static extern uint WTSGetActiveConsoleSessionId();
        [DllImport("kernel32.dll")] static extern IntPtr GetCurrentProcess();
        [DllImport("wtsapi32.dll")] static extern bool WTSQueryUserToken(uint s, out IntPtr t);
        [DllImport("advapi32.dll")] static extern bool OpenProcessToken(IntPtr process, uint access, out IntPtr token);
        [DllImport("advapi32.dll")] static extern bool DuplicateTokenEx(IntPtr h, uint a, IntPtr s, int i, int t, out IntPtr d);
        [DllImport("advapi32.dll")] static extern bool SetTokenInformation(IntPtr token, int cls, ref uint info, uint len);
        [DllImport("userenv.dll")]  static extern bool CreateEnvironmentBlock(out IntPtr e, IntPtr t, bool b);
        [DllImport("userenv.dll")]  static extern bool DestroyEnvironmentBlock(IntPtr e);
        [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
        [DllImport("advapi32.dll", CharSet=CharSet.Unicode)]
        static extern bool CreateProcessAsUserW(IntPtr hToken, string app, string cmd,
            IntPtr pa, IntPtr ta, bool inh, uint flags, IntPtr env, string dir,
            ref STARTUPINFO si, out PROCESS_INFORMATION pi);

        [StructLayout(LayoutKind.Sequential, CharSet=CharSet.Unicode)]
        struct STARTUPINFO { public int cb; public string lpReserved, lpDesktop, lpTitle;
            public int dwX,dwY,dwXSize,dwYSize,dwXCountChars,dwYCountChars,dwFillAttribute,dwFlags;
            public short wShowWindow,cbReserved2; public IntPtr lpReserved2,hStdInput,hStdOutput,hStdError; }
        [StructLayout(LayoutKind.Sequential)]
        struct PROCESS_INFORMATION { public IntPtr hProcess,hThread; public uint dwProcessId,dwThreadId; }
    }

    // =========================================================================
    // Hooks mode — runs in the USER SESSION (spawned by service, or run-once)
    // Does: WDA clear loop + global LL hooks (strips LLMHF_INJECTED)
    // =========================================================================
    internal static class HooksMode
    {
        static IntPtr  _hKbd, _hMouse;
        static HookProc _kbdProc, _mouseProc;  // hold refs — GC must not collect
        static int     _mainTid;
        const  int     WM_REHOOK = 0x8001;

        delegate IntPtr HookProc(int n, IntPtr w, IntPtr l);

        [DllImport("user32.dll")] static extern IntPtr SetWindowsHookEx(int id, HookProc fn, IntPtr hMod, uint tid);
        [DllImport("user32.dll")] static extern bool   UnhookWindowsHookEx(IntPtr h);
        [DllImport("user32.dll")] static extern IntPtr CallNextHookEx(IntPtr h, int n, IntPtr w, IntPtr l);
        [DllImport("user32.dll")] static extern bool   GetWindowDisplayAffinity(IntPtr hw, out uint aff);
        [DllImport("user32.dll", SetLastError=true)] static extern bool SetWindowDisplayAffinity(IntPtr hw, uint aff);
        [DllImport("user32.dll")] static extern bool   EnumWindows(EnumWndProc fn, IntPtr lp);
        [DllImport("user32.dll")] static extern bool   PostThreadMessage(int tid, int msg, IntPtr w, IntPtr l);
        [DllImport("user32.dll")] static extern bool   GetMessage(ref MSG m, IntPtr h, uint f, uint t);
        [DllImport("user32.dll")] static extern bool   TranslateMessage(ref MSG m);
        [DllImport("user32.dll")] static extern IntPtr DispatchMessage(ref MSG m);
        [DllImport("kernel32.dll")] static extern IntPtr GetModuleHandle(string n);
        [DllImport("kernel32.dll")] static extern int   GetCurrentThreadId();
        [DllImport("kernel32.dll")] static extern IntPtr LoadLibrary(string path);
        [DllImport("kernel32.dll")] static extern IntPtr GetProcAddress(IntPtr hMod, string name);
        [DllImport("kernel32.dll")] static extern bool   FreeLibrary(IntPtr hMod);
        [DllImport("user32.dll")]   static extern IntPtr SetWindowsHookExW(int id, IntPtr fn, IntPtr hMod, uint tid);
        // Direct injection (fallback for LDBs with ProcessExtensionPointDisablePolicy)
        [DllImport("user32.dll")]   static extern uint   GetWindowThreadProcessId(IntPtr hwnd, out uint pid);
        [DllImport("kernel32.dll", SetLastError=true)] static extern IntPtr OpenProcess(uint access, bool inh, uint pid);
        [DllImport("kernel32.dll", SetLastError=true)] static extern IntPtr VirtualAllocEx(IntPtr proc, IntPtr addr, uint sz, uint type, uint prot);
        [DllImport("kernel32.dll", SetLastError=true)] static extern bool   WriteProcessMemory(IntPtr proc, IntPtr addr, byte[] buf, uint sz, out uint written);
        [DllImport("kernel32.dll", SetLastError=true)] static extern IntPtr CreateRemoteThread(IntPtr proc, IntPtr sa, uint stack, IntPtr start, IntPtr param, uint flags, out uint tid);
        [DllImport("kernel32.dll")] static extern uint   WaitForSingleObject(IntPtr h, uint ms);
        [DllImport("kernel32.dll")] static extern bool   VirtualFreeEx(IntPtr proc, IntPtr addr, uint sz, uint type);
        [DllImport("kernel32.dll")] static extern uint   GetCurrentProcessId();
        [DllImport("kernel32.dll")] static extern bool   CloseHandle(IntPtr h);
        [DllImport("kernel32.dll")] static extern bool   GetExitCodeThread(IntPtr h, out uint code);
        [DllImport("kernel32.dll", EntryPoint="GetProcAddress")]
        static extern IntPtr GetProcAddressOrd(IntPtr hMod, IntPtr ordinal);

        // Thread-hijack injection support
        [DllImport("kernel32.dll",SetLastError=true)] static extern uint   SuspendThread(IntPtr h);
        [DllImport("kernel32.dll",SetLastError=true)] static extern uint   ResumeThread(IntPtr h);
        [DllImport("kernel32.dll",SetLastError=true)] static extern bool   GetThreadContext(IntPtr h, IntPtr ctx);
        [DllImport("kernel32.dll",SetLastError=true)] static extern bool   SetThreadContext(IntPtr h, IntPtr ctx);
        [DllImport("kernel32.dll",SetLastError=true)] static extern IntPtr VirtualAlloc(IntPtr a, uint s, uint t, uint p);
        [DllImport("kernel32.dll",SetLastError=true)] static extern bool   VirtualFree(IntPtr a, uint s, uint t);
        [DllImport("kernel32.dll",SetLastError=true)] static extern bool   ReadProcessMemory(IntPtr p, IntPtr a, byte[] b, uint s, out uint r);
        [DllImport("kernel32.dll",SetLastError=true)] static extern IntPtr CreateToolhelp32Snapshot(uint f, uint pid);
        [DllImport("kernel32.dll",SetLastError=true)] static extern bool   Thread32First(IntPtr s, ref THREADENTRY32 te);
        [DllImport("kernel32.dll",SetLastError=true)] static extern bool   Thread32Next(IntPtr s, ref THREADENTRY32 te);
        [DllImport("kernel32.dll",SetLastError=true)] static extern IntPtr OpenThread(uint a, bool inh, uint tid);
        [StructLayout(LayoutKind.Sequential)]
        struct THREADENTRY32 { public uint dwSize,cntUsage,th32ThreadID,th32OwnerProcessID; public int tpBasePri,tpDeltaPri; public uint dwFlags; }

        static IntPtr _hGetMsg     = IntPtr.Zero;
        static IntPtr _hDll        = IntPtr.Zero;
        static bool   _dllInjected = false; // wdpcore handles WDA from inside each process
        static string _dllPath     = null;  // path to wdpcore.dll on disk
        static readonly System.Collections.Generic.HashSet<uint> _triedPids = new System.Collections.Generic.HashSet<uint>();
        delegate bool EnumWndProc(IntPtr h, IntPtr l);
        [StructLayout(LayoutKind.Sequential)]
        struct MSG { public IntPtr hwnd; public int message; public IntPtr wParam, lParam; public uint time; public int x,y; }

        [StructLayout(LayoutKind.Sequential)]
        struct KBDLLHOOKSTRUCT { public uint vkCode, scanCode, flags, time; public UIntPtr extra; }
        [StructLayout(LayoutKind.Sequential)]
        struct POINT { public int x, y; }
        [StructLayout(LayoutKind.Sequential)]
        struct MSLLHOOKSTRUCT { public POINT pt; public uint data, flags, time; public UIntPtr extra; }

        static IntPtr KbdProc(int n, IntPtr w, IntPtr l)
        {
            if (n == 0 && l != IntPtr.Zero) {
                var s = Marshal.PtrToStructure<KBDLLHOOKSTRUCT>(l);
                if ((s.flags & 0x12) != 0) { s.flags &= ~0x12u; Marshal.StructureToPtr(s, l, false); }
            }
            return CallNextHookEx(_hKbd, n, w, l);
        }

        static IntPtr MouseProc(int n, IntPtr w, IntPtr l)
        {
            if (n == 0 && l != IntPtr.Zero) {
                var s = Marshal.PtrToStructure<MSLLHOOKSTRUCT>(l);
                if ((s.flags & 0x03) != 0) { s.flags &= ~0x03u; Marshal.StructureToPtr(s, l, false); }
            }
            return CallNextHookEx(_hMouse, n, w, l);
        }

        static void Rehook()
        {
            if (_hKbd   != IntPtr.Zero) { UnhookWindowsHookEx(_hKbd);   _hKbd   = IntPtr.Zero; }
            if (_hMouse != IntPtr.Zero) { UnhookWindowsHookEx(_hMouse); _hMouse = IntPtr.Zero; }
            IntPtr hMod = GetModuleHandle(null);
            _hKbd   = SetWindowsHookEx(13, _kbdProc,   hMod, 0);
            _hMouse = SetWindowsHookEx(14, _mouseProc, hMod, 0);
            Program.Log("Hooks: kbd=" + _hKbd + " mouse=" + _hMouse);
        }

        public static void Run()
        {
            _mainTid  = GetCurrentThreadId();
            _kbdProc   = KbdProc;
            _mouseProc = MouseProc;

            Program.Log("=== /hooks started PID=" + Process.GetCurrentProcess().Id + " ===");
            Rehook();
            InjectDll();

            new Thread(Worker) { IsBackground = true, Name = "HooksWorker" }.Start();

            // Native message loop (Application.Run would also work but this keeps it minimal)
            MSG msg = new MSG();
            while (GetMessage(ref msg, IntPtr.Zero, 0, 0))
            {
                if (msg.message == WM_REHOOK) Rehook();
                TranslateMessage(ref msg);
                DispatchMessage(ref msg);
            }

            UnhookWindowsHookEx(_hKbd);
            UnhookWindowsHookEx(_hMouse);
            if (_hGetMsg != IntPtr.Zero) { UnhookWindowsHookEx(_hGetMsg); _hGetMsg = IntPtr.Zero; }
            if (_hDll    != IntPtr.Zero) { FreeLibrary(_hDll);            _hDll    = IntPtr.Zero; }
        }

        static void InjectDll()
        {
            try {
                string dllPath = System.IO.Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),
                    "wdpcore.dll");
                try { System.IO.File.WriteAllBytes(dllPath, Program.s_wdpcore); }
                catch { /* file in use by another process — use existing copy on disk */ }
                _dllPath = dllPath;
                _hDll = LoadLibrary(dllPath);
                if (_hDll == IntPtr.Zero) { Program.Log("InjectDll: LoadLibrary failed err=" + Marshal.GetLastWin32Error()); return; }
                IntPtr proc = GetProcAddress(_hDll, "GetMsgProc");
                if (proc == IntPtr.Zero) { Program.Log("InjectDll: GetProcAddress failed"); return; }
                _hGetMsg     = SetWindowsHookExW(3, proc, _hDll, 0);  // WH_GETMESSAGE=3
                _dllInjected = _hGetMsg != IntPtr.Zero;
                Program.Log("InjectDll: WH_GETMESSAGE hook=" + _hGetMsg + " active=" + _dllInjected + " err=" + Marshal.GetLastWin32Error());
            } catch (Exception ex) { Program.Log("InjectDll: " + ex.Message); }
        }

        // Fallback injection via CreateRemoteThread for LDBs that block WH_GETMESSAGE
        // (ProcessExtensionPointDisablePolicy). Runs as SYSTEM so OpenProcess succeeds on
        // any non-PPL process regardless of its integrity level.
        static bool DirectInject(uint pid, string dllPath)
        {
            const uint PROCESS_ALL    = 0x1F0FFF;
            const uint MEM_COMMIT_RES = 0x3000;
            const uint PAGE_RW        = 0x04;
            const uint MEM_RELEASE    = 0x8000;
            try
            {
                IntPtr hProc = OpenProcess(PROCESS_ALL, false, pid);
                if (hProc == IntPtr.Zero)
                { Program.Log("DirectInject[" + pid + "]: OpenProcess err=" + Marshal.GetLastWin32Error()); return false; }
                try
                {
                    byte[] pathBytes = Encoding.Unicode.GetBytes(dllPath + "\0");
                    IntPtr remote = VirtualAllocEx(hProc, IntPtr.Zero, (uint)pathBytes.Length, MEM_COMMIT_RES, PAGE_RW);
                    if (remote == IntPtr.Zero)
                    { Program.Log("DirectInject[" + pid + "]: VirtualAllocEx err=" + Marshal.GetLastWin32Error()); return false; }
                    try
                    {
                        uint written;
                        if (!WriteProcessMemory(hProc, remote, pathBytes, (uint)pathBytes.Length, out written))
                        { Program.Log("DirectInject[" + pid + "]: WriteProcessMemory err=" + Marshal.GetLastWin32Error()); return false; }

                        // Build shellcode: SetErrorMode(SEM_FAILCRITICALERRORS) then LoadLibraryW(path).
                        // Calling SetErrorMode FIRST suppresses the "Bad Image" popup that Windows
                        // shows when MicrosoftSignedOnly policy rejects an unsigned DLL — the popup
                        // fires from within the remote thread, so suppressing it there is the fix.
                        IntPtr hK32    = LoadLibrary("kernel32.dll");
                        IntPtr llw     = GetProcAddress(hK32, "LoadLibraryW");
                        IntPtr semAddr = GetProcAddress(hK32, "SetErrorMode");
                        FreeLibrary(hK32);
                        if (llw == IntPtr.Zero)
                        { Program.Log("DirectInject[" + pid + "]: LoadLibraryW addr not found"); return false; }

                        // x64 shellcode (48 bytes):
                        //   sub rsp,28h
                        //   mov ecx, 8001h   ; SEM_FAILCRITICALERRORS|SEM_NOOPENFILEERRORBOX
                        //   mov rax, SetErrorMode; call rax
                        //   mov rcx, dll_path_remote
                        //   mov rax, LoadLibraryW; call rax   ← rax = hModule → thread exit code
                        //   add rsp,28h; ret
                        byte[] sc = new byte[] {
                            0x48,0x83,0xEC,0x28,                    //  0: sub rsp,0x28
                            0xB9,0x01,0x80,0x00,0x00,               //  4: mov ecx,0x8001
                            0x48,0xB8,0,0,0,0,0,0,0,0,             //  9: mov rax,SetErrorMode
                            0xFF,0xD0,                               // 19: call rax
                            0x48,0xB9,0,0,0,0,0,0,0,0,             // 21: mov rcx,dll_path
                            0x48,0xB8,0,0,0,0,0,0,0,0,             // 31: mov rax,LoadLibraryW
                            0xFF,0xD0,                               // 41: call rax
                            0x48,0x83,0xC4,0x28,                    // 43: add rsp,0x28
                            0xC3                                     // 47: ret
                        };
                        Array.Copy(BitConverter.GetBytes(semAddr.ToInt64()), 0, sc, 11, 8);
                        Array.Copy(BitConverter.GetBytes(remote.ToInt64()),   0, sc, 23, 8);
                        Array.Copy(BitConverter.GetBytes(llw.ToInt64()),      0, sc, 33, 8);

                        IntPtr scMem = VirtualAllocEx(hProc, IntPtr.Zero, (uint)sc.Length, 0x3000, 0x40);
                        if (scMem == IntPtr.Zero)
                        { Program.Log("DirectInject[" + pid + "]: sc alloc err=" + Marshal.GetLastWin32Error()); return false; }
                        WriteProcessMemory(hProc, scMem, sc, (uint)sc.Length, out written);

                        uint rtid;
                        IntPtr hThread = CreateRemoteThread(hProc, IntPtr.Zero, 0, scMem, IntPtr.Zero, 0, out rtid);
                        if (hThread == IntPtr.Zero)
                        { Program.Log("DirectInject[" + pid + "]: CreateRemoteThread err=" + Marshal.GetLastWin32Error()); return false; }

                        WaitForSingleObject(hThread, 5000);
                        uint exitCode = 0;
                        GetExitCodeThread(hThread, out exitCode);
                        CloseHandle(hThread);
                        VirtualFreeEx(hProc, scMem, 0, 0x8000); // free shellcode stub
                        if (exitCode > 0x10000) {
                            Program.Log("DirectInject[" + pid + "]: LoadLibraryW OK hmod=0x" + exitCode.ToString("X"));
                            return true;
                        }
                        // exitCode <= 0x10000: either LoadLibraryW returned NULL (signature policy)
                        // or Mode 5 RtlUserThreadStart hook killed the thread with ExitThread(1).
                        // Fall through to manual-map + thread-hijack injection.
                        Program.Log("DirectInject[" + pid + "]: LoadLibraryW returned 0x" + exitCode.ToString("X") + " — trying ManualMap");
                        return ManualMapInject(pid);
                    }
                    finally { VirtualFreeEx(hProc, remote, 0, MEM_RELEASE); }
                }
                finally { CloseHandle(hProc); }
            }
            catch (Exception ex) { Program.Log("DirectInject[" + pid + "]: " + ex.Message); return false; }
        }

        // Manual-map injection — maps wdpcore.dll into target process without LoadLibraryW.
        // Bypasses ProcessSignaturePolicy(MicrosoftSignedOnly) because Windows never sees a
        // LoadLibrary call; we write the PE sections directly and call DllMain via shellcode.
        static bool ManualMapInject(uint pid)
        {
            try
            {
                byte[] dll = Program.s_wdpcore;
                if (dll == null || dll.Length < 0x40)
                { Program.Log("ManualMap[" + pid + "]: no embedded DLL"); return false; }

                // ── Parse PE headers ─────────────────────────────────────────
                int  lfanew   = BitConverter.ToInt32(dll, 0x3C);
                if (BitConverter.ToUInt32(dll, lfanew) != 0x00004550)
                { Program.Log("ManualMap[" + pid + "]: bad PE sig"); return false; }

                int  fileHdr  = lfanew + 4;
                ushort numSec = BitConverter.ToUInt16(dll, fileHdr + 2);
                ushort optSz  = BitConverter.ToUInt16(dll, fileHdr + 16);
                int  optHdr   = fileHdr + 20;

                if (BitConverter.ToUInt16(dll, optHdr) != 0x020B)   // PE32+ only
                { Program.Log("ManualMap[" + pid + "]: not PE32+"); return false; }

                uint  ep        = BitConverter.ToUInt32(dll, optHdr + 16);
                ulong prefBase  = BitConverter.ToUInt64(dll, optHdr + 24);
                uint  imgSz     = BitConverter.ToUInt32(dll, optHdr + 56);
                uint  hdrSz     = BitConverter.ToUInt32(dll, optHdr + 60);
                int   dataDirs  = optHdr + 112;
                uint  importRVA = BitConverter.ToUInt32(dll, dataDirs + 1*8);
                uint  relocRVA  = BitConverter.ToUInt32(dll, dataDirs + 5*8);
                uint  relocSz   = BitConverter.ToUInt32(dll, dataDirs + 5*8 + 4);

                // ── Build flat mapped image (file layout → virtual layout) ───
                byte[] mapped = new byte[imgSz];
                Array.Copy(dll, 0, mapped, 0, Math.Min((int)hdrSz, dll.Length));

                int secBase = optHdr + optSz;
                for (int i = 0; i < numSec; i++)
                {
                    int s    = secBase + i * 40;
                    uint va  = BitConverter.ToUInt32(dll, s + 12);
                    uint rsz = BitConverter.ToUInt32(dll, s + 16);
                    uint rof = BitConverter.ToUInt32(dll, s + 20);
                    if (rsz > 0 && rof + rsz <= dll.Length && va + rsz <= imgSz)
                        Array.Copy(dll, (int)rof, mapped, (int)va, (int)rsz);
                }

                // ── Allocate in target ───────────────────────────────────────
                const uint PROC_ALL    = 0x1F0FFF;
                const uint MEM_CR      = 0x3000;   // MEM_COMMIT | MEM_RESERVE
                const uint PAGE_XRW    = 0x40;     // PAGE_EXECUTE_READWRITE
                const uint MEM_REL     = 0x8000;

                IntPtr hProc = OpenProcess(PROC_ALL, false, pid);
                if (hProc == IntPtr.Zero)
                { Program.Log("ManualMap[" + pid + "]: OpenProcess err=" + Marshal.GetLastWin32Error()); return false; }
                try
                {
                    // Try preferred base first, fall back to anywhere
                    IntPtr remote = VirtualAllocEx(hProc, (IntPtr)(long)prefBase, imgSz, MEM_CR, PAGE_XRW);
                    if (remote == IntPtr.Zero)
                        remote = VirtualAllocEx(hProc, IntPtr.Zero, imgSz, MEM_CR, PAGE_XRW);
                    if (remote == IntPtr.Zero)
                    { Program.Log("ManualMap[" + pid + "]: VirtualAllocEx err=" + Marshal.GetLastWin32Error()); return false; }

                    long delta = (long)remote - (long)prefBase;
                    Program.Log("ManualMap[" + pid + "]: remote=0x" + remote.ToString("X") + " delta=" + delta);

                    // ── Fix base relocations ─────────────────────────────────
                    if (relocRVA != 0 && delta != 0)
                    {
                        uint pos = relocRVA;
                        while (pos < relocRVA + relocSz)
                        {
                            uint pageRVA = BitConverter.ToUInt32(mapped, (int)pos);
                            uint blkSz   = BitConverter.ToUInt32(mapped, (int)pos + 4);
                            if (blkSz == 0) break;
                            int  count   = (int)(blkSz - 8) / 2;
                            for (int r = 0; r < count; r++)
                            {
                                ushort entry = BitConverter.ToUInt16(mapped, (int)(pos + 8 + r * 2));
                                int    type  = entry >> 12;
                                int    off   = entry & 0xFFF;
                                if (type == 10) // IMAGE_REL_BASED_DIR64
                                {
                                    long val = BitConverter.ToInt64(mapped, (int)(pageRVA + off));
                                    Array.Copy(BitConverter.GetBytes(val + delta), 0, mapped, (int)(pageRVA + off), 8);
                                }
                            }
                            pos += blkSz;
                        }
                    }

                    // ── Fix imports ──────────────────────────────────────────
                    // System DLL base addresses are identical in all processes on
                    // the same OS instance, so resolving in our process is valid.
                    if (importRVA != 0)
                    {
                        uint desc = importRVA;
                        while (true)
                        {
                            uint origThunk = BitConverter.ToUInt32(mapped, (int)desc);
                            uint iatRVA    = BitConverter.ToUInt32(mapped, (int)desc + 16);
                            uint nameRVA   = BitConverter.ToUInt32(mapped, (int)desc + 12);
                            if (origThunk == 0 && nameRVA == 0) break;

                            int nEnd = (int)nameRVA;
                            while (nEnd < mapped.Length && mapped[nEnd] != 0) nEnd++;
                            string modName = Encoding.ASCII.GetString(mapped, (int)nameRVA, nEnd - (int)nameRVA);
                            IntPtr hMod = GetModuleHandle(modName);
                            if (hMod == IntPtr.Zero) hMod = LoadLibrary(modName);

                            uint thunkPtr = origThunk != 0 ? origThunk : iatRVA;
                            uint iatPtr   = iatRVA;
                            while (true)
                            {
                                ulong td = BitConverter.ToUInt64(mapped, (int)thunkPtr);
                                if (td == 0) break;
                                IntPtr fn;
                                if ((td & 0x8000000000000000UL) != 0)
                                    fn = GetProcAddressOrd(hMod, (IntPtr)(td & 0xFFFF));
                                else
                                {
                                    int hnRVA = (int)(td & 0x7FFFFFFF);
                                    int fnEnd = hnRVA + 2;
                                    while (fnEnd < mapped.Length && mapped[fnEnd] != 0) fnEnd++;
                                    string fnName = Encoding.ASCII.GetString(mapped, hnRVA + 2, fnEnd - (hnRVA + 2));
                                    fn = GetProcAddress(hMod, fnName);
                                }
                                Array.Copy(BitConverter.GetBytes((long)fn), 0, mapped, (int)iatPtr, 8);
                                thunkPtr += 8; iatPtr += 8;
                            }
                            desc += 20; // sizeof IMAGE_IMPORT_DESCRIPTOR
                        }
                    }

                    // ── Write mapped image to target ─────────────────────────
                    uint written;
                    if (!WriteProcessMemory(hProc, remote, mapped, imgSz, out written))
                    { Program.Log("ManualMap[" + pid + "]: WPM err=" + Marshal.GetLastWin32Error()); return false; }

                    long epAbs = (long)remote + ep;
                    long hm64  = (long)remote;

                    // ── Try thread-hijack delivery first (bypasses RtlUserThreadStart hook / Mode 5) ──
                    // Hijacks an EXISTING thread: no new thread → RtlUserThreadStart hook never fires.
                    bool injected = HijackThreadDllMain(hProc, pid, hm64, epAbs);
                    if (injected)
                    {
                        Program.Log("ManualMap[" + pid + "]: OK via thread-hijack ep=0x" + epAbs.ToString("X"));
                        return true;
                    }

                    // ── Fallback: CreateRemoteThread ──────────────────────────────────────────────────
                    // Works for Modes 1-4. Killed by Mode 5 (RtlUserThreadStart hook), but logged.
                    Program.Log("ManualMap[" + pid + "]: hijack failed, trying CreateRemoteThread");
                    byte[] sc = new byte[] {
                        0x48, 0x83, 0xEC, 0x28,              // sub rsp, 0x28
                        0x48, 0xB9, 0,0,0,0, 0,0,0,0,        // mov rcx, hModule
                        0xBA, 0x01, 0x00, 0x00, 0x00,         // mov edx, 1
                        0x45, 0x33, 0xC0,                     // xor r8d, r8d
                        0x48, 0xB8, 0,0,0,0, 0,0,0,0,        // mov rax, DllMain
                        0xFF, 0xD0,                           // call rax
                        0x48, 0x83, 0xC4, 0x28,              // add rsp, 0x28
                        0xC3                                  // ret
                    };
                    Array.Copy(BitConverter.GetBytes(hm64),  0, sc, 6,  8);
                    Array.Copy(BitConverter.GetBytes(epAbs), 0, sc, 24, 8);
                    IntPtr scMem = VirtualAllocEx(hProc, IntPtr.Zero, (uint)sc.Length, MEM_CR, PAGE_XRW);
                    if (scMem == IntPtr.Zero)
                    { Program.Log("ManualMap[" + pid + "]: sc alloc err=" + Marshal.GetLastWin32Error()); return false; }
                    WriteProcessMemory(hProc, scMem, sc, (uint)sc.Length, out written);
                    uint rtid;
                    IntPtr hCrtThread = CreateRemoteThread(hProc, IntPtr.Zero, 0, scMem, IntPtr.Zero, 0, out rtid);
                    if (hCrtThread == IntPtr.Zero)
                    { Program.Log("ManualMap[" + pid + "]: CRT err=" + Marshal.GetLastWin32Error()); return false; }
                    WaitForSingleObject(hCrtThread, 5000);
                    CloseHandle(hCrtThread);
                    Program.Log("ManualMap[" + pid + "]: OK via CRT ep=0x" + epAbs.ToString("X"));
                    return true;
                }
                finally { CloseHandle(hProc); }
            }
            catch (Exception ex) { Program.Log("ManualMap[" + pid + "]: " + ex.Message); return false; }
        }

        // Inject DllMain via thread hijack — suspends an existing thread in the target,
        // redirects its RIP to shellcode that saves all volatile registers, calls
        // DllMain(hModule, DLL_PROCESS_ATTACH, 0), restores registers, and jumps back.
        // No new thread is created, so RtlUserThreadStart hooks never fire.
        //
        // Shellcode DATA_AREA layout (written into target at remoteBase+256):
        //   +0  saved_rax   +8  saved_r11   +16 saved_rcx  +24 saved_rdx
        //   +32 saved_r8    +40 saved_r9    +48 saved_r10
        //   +56 original_rsp (saved by shellcode)
        //   +64 rflags      (saved by shellcode)
        //   +72 original_rip (filled from thread context before hijack)
        //   +80 hModule     (filled before hijack)
        //   +88 dllMain     (filled before hijack)
        //   +96 done_flag   (shellcode sets to 1 after DllMain returns)
        static bool HijackThreadDllMain(IntPtr hProc, uint pid, long hModule, long dllMain)
        {
            const uint TH32CS_SNAPTHREAD = 4;
            const uint THREAD_ALL = 0x1FFFFF;
            const uint MEM_CR    = 0x3000;
            const uint PAGE_XRW  = 0x40;
            const uint PAGE_RW   = 0x04;
            const uint MEM_REL   = 0x8000;
            const uint CONTEXT_FULL = 0x10001F;
            const int  CTX_SIZE  = 1232;
            const int  CTX_FLAGS = 48;
            const int  CTX_RIP   = 248;

            // Shellcode bytes (164 bytes).
            // DATA_AREA absolute address is embedded at sc[15..22] and sc[105..112].
            byte[] sc = new byte[] {
                // sub rsp,16 | mov [rsp],rax | mov [rsp+8],r11
                0x48,0x83,0xEC,0x10,
                0x48,0x89,0x04,0x24,
                0x4C,0x89,0x5C,0x24,0x08,
                // mov r11, DATA_AREA  (8-byte addr at bytes [15..22])
                0x49,0xBB,0,0,0,0,0,0,0,0,
                // mov rax,[rsp] | mov [r11],rax  (save original rax)
                0x48,0x8B,0x04,0x24,  0x49,0x89,0x03,
                // mov rax,[rsp+8] | mov [r11+8],rax  (save original r11)
                0x48,0x8B,0x44,0x24,0x08,  0x49,0x89,0x43,0x08,
                // add rsp,16
                0x48,0x83,0xC4,0x10,
                // save rcx,rdx,r8,r9,r10,rsp,rflags
                0x49,0x89,0x4B,0x10,  // [r11+16]=rcx
                0x49,0x89,0x53,0x18,  // [r11+24]=rdx
                0x4D,0x89,0x43,0x20,  // [r11+32]=r8
                0x4D,0x89,0x4B,0x28,  // [r11+40]=r9
                0x4D,0x89,0x53,0x30,  // [r11+48]=r10
                0x49,0x89,0x63,0x38,  // [r11+56]=rsp
                0x9C,0x58,            // pushfq; pop rax
                0x49,0x89,0x43,0x40,  // [r11+64]=rax (rflags)
                // align stack and call DllMain(hModule,1,0)
                0x48,0x83,0xE4,0xF0,  // and rsp,~0xF
                0x48,0x83,0xEC,0x28,  // sub rsp,0x28
                0x49,0x8B,0x4B,0x50,  // mov rcx,[r11+80]  hModule
                0xBA,0x01,0x00,0x00,0x00, // mov edx,1
                0x45,0x33,0xC0,       // xor r8d,r8d
                0x49,0x8B,0x43,0x58,  // mov rax,[r11+88]  dllMain
                0xFF,0xD0,            // call rax
                0x48,0x83,0xC4,0x28,  // add rsp,0x28
                // reload r11 = DATA_AREA  (8-byte addr at bytes [105..112])
                0x49,0xBB,0,0,0,0,0,0,0,0,
                // set done flag: mov qword [r11+96],1
                0x49,0xC7,0x43,0x60,0x01,0x00,0x00,0x00,
                // restore rflags
                0x49,0x8B,0x43,0x40,  // mov rax,[r11+64]
                0x50,0x9D,            // push rax; popfq
                // restore rcx,rdx,r8,r9,r10
                0x49,0x8B,0x4B,0x10,  // mov rcx,[r11+16]
                0x49,0x8B,0x53,0x18,  // mov rdx,[r11+24]
                0x4D,0x8B,0x43,0x20,  // mov r8,[r11+32]
                0x4D,0x8B,0x4B,0x28,  // mov r9,[r11+40]
                0x4D,0x8B,0x53,0x30,  // mov r10,[r11+48]
                // mov rax,[r11+72] (orig rip) | mov rsp,[r11+56] (orig rsp)
                0x49,0x8B,0x43,0x48,
                0x49,0x8B,0x63,0x38,
                // push rax (orig rip onto orig stack) | mov rax,[r11] | mov r11,[r11+8] | ret
                0x50,
                0x49,0x8B,0x03,
                0x4D,0x8B,0x5B,0x08,
                0xC3
            };

            try
            {
                // ── Find a target thread ──────────────────────────────────────
                uint targetTid = 0;
                IntPtr snap = CreateToolhelp32Snapshot(TH32CS_SNAPTHREAD, 0);
                if (snap != (IntPtr)(-1))
                {
                    var te = new THREADENTRY32 { dwSize = (uint)Marshal.SizeOf(typeof(THREADENTRY32)) };
                    if (Thread32First(snap, ref te)) do {
                        if (te.th32OwnerProcessID == pid) { targetTid = te.th32ThreadID; break; }
                    } while (Thread32Next(snap, ref te));
                    CloseHandle(snap);
                }
                if (targetTid == 0)
                { Program.Log("Hijack[" + pid + "]: no threads found"); return false; }

                // ── Allocate hijack block in target: 256 code + 128 data ─────
                IntPtr remoteBase = VirtualAllocEx(hProc, IntPtr.Zero, 512, MEM_CR, PAGE_XRW);
                if (remoteBase == IntPtr.Zero)
                { Program.Log("Hijack[" + pid + "]: alloc err=" + Marshal.GetLastWin32Error()); return false; }

                long dataArea = remoteBase.ToInt64() + 256;

                // Patch shellcode with DATA_AREA address at bytes [15..22] and [105..112]
                Array.Copy(BitConverter.GetBytes(dataArea), 0, sc, 15, 8);
                Array.Copy(BitConverter.GetBytes(dataArea), 0, sc, 105, 8);

                // Write data area: hModule at +80, dllMain at +88, rest zeros
                byte[] data = new byte[128];
                Array.Copy(BitConverter.GetBytes(hModule), 0, data, 80, 8);
                Array.Copy(BitConverter.GetBytes(dllMain), 0, data, 88, 8);

                uint written;
                WriteProcessMemory(hProc, remoteBase, sc, (uint)sc.Length, out written);
                WriteProcessMemory(hProc, (IntPtr)dataArea, data, 128, out written);

                // ── Suspend target thread and get/set context ─────────────────
                IntPtr hThread = OpenThread(THREAD_ALL, false, targetTid);
                if (hThread == IntPtr.Zero)
                { Program.Log("Hijack[" + pid + "]: OpenThread err=" + Marshal.GetLastWin32Error()); return false; }

                SuspendThread(hThread);

                // Allocate 16-byte-aligned CONTEXT buffer in our own process
                IntPtr ctxMem = VirtualAlloc(IntPtr.Zero, (uint)(CTX_SIZE + 16), 0x3000, PAGE_RW);
                if (ctxMem == IntPtr.Zero)
                { ResumeThread(hThread); CloseHandle(hThread); return false; }

                long ctxAligned = (ctxMem.ToInt64() + 15) & ~15L;
                IntPtr ctx = (IntPtr)ctxAligned;
                Marshal.WriteInt32((IntPtr)(ctx.ToInt64() + CTX_FLAGS), (int)CONTEXT_FULL);

                if (!GetThreadContext(hThread, ctx))
                {
                    Program.Log("Hijack[" + pid + "]: GetThreadContext err=" + Marshal.GetLastWin32Error());
                    VirtualFree(ctxMem, 0, MEM_REL);
                    ResumeThread(hThread); CloseHandle(hThread); return false;
                }

                long origRip = Marshal.ReadInt64((IntPtr)(ctx.ToInt64() + CTX_RIP));

                // Write original RIP into data area at offset 72
                byte[] ripBuf = BitConverter.GetBytes(origRip);
                WriteProcessMemory(hProc, (IntPtr)(dataArea + 72), ripBuf, 8, out written);

                // Redirect thread to our shellcode
                Marshal.WriteInt64((IntPtr)(ctx.ToInt64() + CTX_RIP), remoteBase.ToInt64());
                bool setOk = SetThreadContext(hThread, ctx);
                VirtualFree(ctxMem, 0, MEM_REL);

                if (!setOk)
                {
                    Program.Log("Hijack[" + pid + "]: SetThreadContext err=" + Marshal.GetLastWin32Error());
                    ResumeThread(hThread); CloseHandle(hThread); return false;
                }

                ResumeThread(hThread);
                CloseHandle(hThread);

                // ── Wait for done flag (shellcode sets data[96]=1 after DllMain) ──
                byte[] doneBuf = new byte[4];
                uint rd;
                IntPtr doneAddr = (IntPtr)(dataArea + 96);
                for (int i = 0; i < 300; i++) // 3 seconds max
                {
                    Thread.Sleep(10);
                    ReadProcessMemory(hProc, doneAddr, doneBuf, 4, out rd);
                    if (BitConverter.ToInt32(doneBuf, 0) != 0) break;
                }

                Program.Log("Hijack[" + pid + "]: done origRip=0x" + origRip.ToString("X")
                    + " doneFlag=" + BitConverter.ToInt32(doneBuf, 0));
                return true;
            }
            catch (Exception ex) { Program.Log("Hijack[" + pid + "]: " + ex.Message); return false; }
        }

        static void Worker()
        {
            uint lastProcs = 0;
            int  cycles    = 0;
            while (true)
            {
                Thread.Sleep(150);

                // WDA clear — only when wdpcore injection is not active.
                // When active, wdpcore handles WDA from inside each process (more reliable).
                if (!_dllInjected)
                {
                    EnumWindows((hw, _) => {
                        uint aff;
                        if (GetWindowDisplayAffinity(hw, out aff) && aff != 0)
                        {
                            bool ok = SetWindowDisplayAffinity(hw, 0);
                            uint err = (uint)Marshal.GetLastWin32Error();
                            Program.Log("WDA hwnd=0x" + hw.ToString("X") + " ok=" + ok + " err=" + err);
                        }
                        return true;
                    }, IntPtr.Zero);
                }

                // DirectInject fallback: every 3 s scan for WDA windows not yet injected via hook.
                // Catches LDBs with ProcessExtensionPointDisablePolicy that block WH_GETMESSAGE injection.
                if (_dllPath != null && cycles % 20 == 0)
                {
                    uint selfPid = GetCurrentProcessId();
                    EnumWindows((hw, _) => {
                        uint aff;
                        if (!GetWindowDisplayAffinity(hw, out aff) || aff == 0) return true;
                        uint pid = 0;
                        GetWindowThreadProcessId(hw, out pid);
                        if (pid == 0 || pid == selfPid) return true;
                        lock (_triedPids)
                        {
                            if (_triedPids.Contains(pid)) return true;
                            _triedPids.Add(pid);
                        }
                        Program.Log("DirectInject: WDA window hwnd=0x" + hw.ToString("X8") + " pid=" + pid);
                        DirectInject(pid, _dllPath);
                        return true;
                    }, IntPtr.Zero);
                }

                // Detect new processes → re-register hooks so we stay FIRST in LIFO chain
                uint procs = 0;
                try { procs = (uint)Process.GetProcesses().Length; } catch { }
                if (procs != lastProcs && lastProcs != 0)
                {
                    lastProcs = procs;
                    Thread.Sleep(600);
                    lock (_triedPids) { _triedPids.Clear(); } // new process arrived — retry DirectInject scan
                    PostThreadMessage(_mainTid, WM_REHOOK, IntPtr.Zero, IntPtr.Zero);
                }
                else if (lastProcs == 0) lastProcs = procs;

                if (++cycles % 400 == 0)
                    Program.Log("heartbeat cycles=" + cycles + " procs=" + procs);
            }
        }
    }

